declare
d_exists number;
begin
select 1 into d_exists from REGISTRO
where CHIAVE = 'PRODUCTS/*/AREA_CLIENTI/CARDCODE' and STRINGA = 'CardCode';

update REGISTRO set VALORE = '${sap_cardcode}'
where CHIAVE = 'PRODUCTS/*/AREA_CLIENTI/CARDCODE' and STRINGA = 'CardCode';
exception
when no_data_found then
insert into REGISTRO (CHIAVE, STRINGA, COMMENTO, VALORE)
values ('PRODUCTS/*/AREA_CLIENTI/CARDCODE',
'CardCode',
'cardcode dell''ente che utilizza l''installazione di AD4. Valore stabilito in fase di distribuzione. Modificare cum grano salis',
'${sap_cardcode}');
end;

declare
d_exists number;
begin
select 1 into d_exists from REGISTRO
where CHIAVE = 'PRODUCTS/*/AREA_CLIENTI/URL_ROOT' and STRINGA = 'UrlAreaClienti';

update REGISTRO set VALORE = 'https://areaclienti.finmatica.it'
where CHIAVE = 'PRODUCTS/*/AREA_CLIENTI/URL_ROOT' and STRINGA = 'UrlAreaClienti';
exception
when no_data_found then
insert into REGISTRO (CHIAVE, STRINGA, COMMENTO, VALORE)
values ('PRODUCTS/*/AREA_CLIENTI/URL_ROOT',
'UrlAreaClienti',
'URL dell''area clienti. Valore stabilito in fase di distribuzione. Modificare cum grano salis',
'https://areaclienti.finmatica.it');
end;
